/bin/bash -lc "python - <<'PY'
import requests
for repo in ('numpy','pandas'):
    u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/'
    r=requests.get(u,params={'limit':20,'page':1,'onlyActiveTags':'true'},timeout=60)
    print(repo, r.status_code)
    if r.ok:
        for t in r.json().get('tags',[])[:6]: print(' ',t['name'])
PY"

